"""Pydantic schemas for Gemini Structured Outputs.

Enforces strict JSON schema generation and deterministic structural parsing.
"""
from __future__ import annotations

from typing import Literal
from pydantic import BaseModel, Field


class EditorialPickSchema(BaseModel):
    """Schema for a single editorial pick generated by Gemini."""
    article_ids: list[str] = Field(
        description="List of candidate article IDs that support this story"
    )
    score: int = Field(
        ge=0,
        le=100,
        description="Editorial significance score (0-100). Only 82+ are notified.",
    )
    kind: Literal["NEW", "UPDATE"] = Field(
        description="'NEW' for first-time stories, 'UPDATE' for major developments on previously alerted stories."
    )
    parent_story_id: str = Field(
        default="",
        description="Exact story_id from previously_alerted if kind is 'UPDATE', else empty string.",
    )
    development_tr: str = Field(
        default="",
        description="Concrete new factual development in Turkish if kind is 'UPDATE', else empty string.",
    )
    headline_tr: str = Field(
        min_length=5,
        max_length=200,
        description="Clean, impactful Turkish editorial headline.",
    )
    cover_title_tr: str = Field(
        min_length=3,
        max_length=150,
        description="Punchy 3-8 word cover title for Instagram post cover image.",
    )
    caption_idea_tr: str = Field(
        min_length=10,
        max_length=600,
        description="Draft Instagram caption (1-2 sentences) in Turkish.",
    )
    why_efso_tr: str = Field(
        min_length=5,
        max_length=300,
        description="Short reason why this story is valuable for @efsomagazin's pop-culture audience.",
    )
    suggested_format: Literal["POST", "CAROUSEL", "REEL"] = Field(
        description="Recommended Instagram content format."
    )
    category: Literal["GLOBAL", "YERLI", "VIRAL", "MUZIK_DIZI", "INTERNET"] = Field(
        description="Editorial content category."
    )


class EditorialDecisionBatch(BaseModel):
    """Batch of editorial picks returned by Gemini."""
    picks: list[EditorialPickSchema] = Field(
        default_factory=list,
        description="Selected editorial stories. Empty list if no candidate meets the high threshold.",
    )
